// The load per core, or NaN when the load or the core count is not a number, or there are no cores.
export function loadPerCore({ load, cpus }) {
  if (!Number.isFinite(load) || !Number.isFinite(cpus) || cpus <= 0) return Number.NaN;
  return load / cpus;
}

// A time bound ms, times the 1-minute load per core when that is over 1, so a test's wall-clock
// bound holds on a busy shared machine. Load and cores default to this machine's.
export function stretchByLoad(ms, { load = os.loadavg()[0], cpus = os.cpus().length } = {}) {
  const perCore = loadPerCore({ load, cpus });
  return Number.isFinite(perCore) && perCore > 1 ? Math.round(ms * perCore) : ms;
}

// The limit for one test: a positive SLOW_TEST_LIMIT_MS (explicit) exactly, else LIMIT_MS
// stretched by the load (stretchByLoad).
export function guardLimitMs({ explicit, load, cpus }) {
  const set = Number(explicit);
  if (Number.isFinite(set) && set > 0) return set;
  return stretchByLoad(LIMIT_MS, { load, cpus });
}

// Null when the test took at most limitMs or is listed, else the message that fails it.
export function slowTestError({ fullName, ms, list = SLOW_TESTS, limitMs = LIMIT_MS }) {
  if (ms <= limitMs || Object.hasOwn(list, fullName)) return null;
  return `${fullName} took ${(ms / 1000).toFixed(1)} s, over the ${limitMs / 1000} s limit for one test. Make it faster, or list it in SLOW_TESTS in test/slow-tests.mjs with the reason it waits.`;
}

// What the guard does with one test: null when it is listed or within the limit (guardLimitMs),
// else { level: 'fail' | 'warn', message }. Over the limit on an idle machine fails; on a busy
// one it warns, unless SLOW_TEST_LIMIT_MS (explicit) set the limit. mode 'report'
// (SLOW_TEST_GUARD) warns instead of every failure. A load that cannot be read counts as idle.
export function slowTestFinding({ fullName, ms, list = SLOW_TESTS, explicit, mode, load, cpus }) {
  const limitMs = guardLimitMs({ explicit, load, cpus });
  if (Object.hasOwn(list, fullName) || ms <= limitMs) return null;
  const base = slowTestError({ fullName, ms, list, limitMs });
  const set = Number(explicit);
  const perCore = loadPerCore({ load, cpus });
  const busy = Number.isFinite(perCore) && perCore >= IDLE_LOAD_PER_CORE && !(Number.isFinite(set) && set > 0);
  if (busy) {
    return {
      level: 'warn',
      message: `${GUARD_WARNING} ${fullName} took ${(ms / 1000).toFixed(1)} s, over the ${limitMs / 1000} s limit for one test, at load ${perCore.toFixed(1)} per core. Not failed: the machine is busy (a test fails only under ${IDLE_LOAD_PER_CORE} per core).`,
    };
  }
  if (mode === 'report') return { level: 'warn', message: `${GUARD_WARNING} ${base} Not failed here (SLOW_TEST_GUARD=report); it fails npm test on an idle machine.` };
  return { level: 'fail', message: base };
}
